WITH valid AS (SELECT id, product_id, quantity, unit_price, COALESCE(unit_price, 0) AS unit_price_filled FROM order_items WHERE quantity = 6) SELECT id, product_id, quantity, unit_price, unit_price_filled, NTILE(4) OVER (PARTITION BY product_id ORDER BY unit_price_filled DESC, id) AS unit_price_filled_bucket, PERCENT_RANK() OVER (PARTITION BY product_id ORDER BY quantity) AS quantity_percent_rank, AVG(quantity) OVER w_running AS quantity_avg_2_prior FROM valid WHERE unit_price BETWEEN 340 AND 390 WINDOW w_running AS (ORDER BY unit_price, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING);
